python
def priorityBasketFirstQualifyingSlip(readings, k):
    a=readings
    out=[]
    import heapq
    heap=a[:]
    heapq.heapify(heap)
    while heap: out.append(heapq.heappop(heap))
    return next((x for x in out if x>=k),-1)


java
class Solution {
  public int priorityBasketFirstQualifyingSlip(int[] readings, int k) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {PriorityQueue<Integer>heap=new PriorityQueue<>();for(int x:a)heap.add(x);while(!heap.isEmpty())out.add(heap.remove());}
    for(int x:out)if(x>=k)return x;return -1;
  }
}
